tests.test_code:
/* The quotes around the braces
   are just more characters: {"{}"} */
TEST_ASSERT_TRUE(is_paired("\"{}\""));

char value[3];
value[0] = '{';
value[1] = '}';
value[2] = '\0';
TEST_ASSERT_TRUE(is_paired(value));

const char *pairs[] = {"{}", "[]", "()"};
for (size_t i = 0; i < 3; i++) {
    if (i != 1) {
        TEST_ASSERT_TRUE(is_paired(pairs[i]));
    }
}
